pctRank:
function pctRank(history,value){
  const a=(history||[]).map(Number).filter(Number.isFinite).sort((x,y)=>x-y);
  if(!a.length||!isNum(value)) return null;
  const v=Number(value);
  let below=0,equal=0;
  for(const x of a){ if(x<v) below++; else if(x===v) equal++; }
  return 100*((below+0.5*equal)/a.length);
}

label:
function label(pol){
return pol>0?'Favorevole':pol<0?'Contrario':'Neutrale';
}

series:
function series(ccy,key){
  if(key!=='labour' && key!=='inflation') return {ccy,key,status:'WITHHELD',reason:'NOT_IN_DUAL_THERMOMETER'};
  const d=ROOT()?.currencies?.[ccy]?.[key];
  if(!d||!validated(d))return {ccy,key,status:'WITHHELD',score:null,label:'WITHHELD'};
  const p=pctRank(d.history,d.latest_value);
  if(p==null)return {ccy,key,status:'WITHHELD',score:null,label:'WITHHELD'};
  const score=p;
  return {ccy,key,status:'ACTIVE',percentile:p,score,label:label(score),
          latest_value:Number(d.latest_value),direction:d.direction||'WITHHELD',
          acceleration:d.acceleration||'WITHHELD'};
}

currency:
function currency(ccy){
  const p=P(), d=p?.currencies?.[ccy];
  if(!d) return {ccy,status:'WITHHELD',reason:'NO_RECORD'};
  const v=d.validation||{};
  const active=d.status==='ACTIVE' &&
    v.source_validated===true &&
    v.asof_validated===true &&
    v.meeting_path_validated===true &&
    v.changes_validated===true;
  if(!active) return {ccy,status:'WITHHELD',reason:'NOT_FULLY_VALIDATED',raw:d};
  return {ccy,status:'ACTIVE',raw:d};
}
